import {forecast,reviewModel,scenario,SECTORS,quarterIndex,quarterLabel,isNumber} from './model.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',sliders:'M4 4v16 M12 4v16 M20 4v16 M1 8h6 M9 16h6 M17 10h6',database:'M21 5c0 2-4 3-9 3S3 7 3 5s4-3 9-3 9 1 9 3z M3 5v14c0 2 4 3 9 3s9-1 9-3V5 M3 12c0 2 4 3 9 3s9-1 9-3',book:'M12 5c-3-2-7-2-10-1v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1z M12 5v15',github:'M9 19c-4 1-4-2-6-2 M15 22v-4c0-1-.3-2-1-2 4 0 7-2 7-6 0-2-1-3-2-4 0-1 0-3-1-4-2 0-3 1-4 2-2-1-4-1-6 0-1-1-2-2-4-2-1 1-1 3-1 4-1 1-2 2-2 4 0 4 3 6 7 6-1 1-1 2-1 3v3',download:'M12 3v12 M7 10l5 5 5-5 M4 15v6h16v-6',refresh:'M20 7a9 9 0 0 0-15-2L2 8 M2 2v6h6 M4 17a9 9 0 0 0 15 2l3-3 M22 22v-6h-6',print:'M6 9V2h12v7 M6 18H3V9h18v9h-3 M6 14h12v8H6z M17 12h1',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',external:'M14 3h7v7 M21 3l-11 11 M10 3H3v18h18v-7',arrow:'M4 12h16 M14 6l6 6-6 6',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 11v6 M12 7v.1',chart:'M3 3v18h18 M6 15l5-6 4 3 6-7',layers:'M12 2L2 8l10 6 10-6-10-6 M2 13l10 6 10-6 M2 18l10 6 10-6'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=(v,d=2)=>isNumber(v)?new Intl.NumberFormat('en-GB',{style:'percent',minimumFractionDigits:d,maximumFractionDigits:d}).format(v):'—';
const num=(v,d=1)=>isNumber(v)?new Intl.NumberFormat('en-GB',{minimumFractionDigits:d,maximumFractionDigits:d}).format(v):'—';
const pp=(v,d=2)=>isNumber(v)?`${v>=0?'+':''}${num(v,d)}`:'—';
const dateStr=s=>s?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kuala_Lumpur'}).format(new Date(s.includes('T')?s:s+'T12:00:00Z')):'Unverified';
const stamp=s=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Kuala_Lumpur'}).format(new Date(s))+' MYT';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const period=s=>/^\d{4}Q[1-4]$/.test(s||'')?`Q${s.at(-1)} ${s.slice(0,4)}`:s?.length===10?new Intl.DateTimeFormat('en-GB',{month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z')):s||'—';
let data,result,review,mode='Auto',selectedSector='services',adjustments={},config={repository:'',workflow:'update-and-deploy.yml'},local=false,busy=false,chartRange=8;
let explorer={type:'monthly',year:'2026'},currentView='overview';
const titles={overview:['A clearer view of quarterly growth.','Track the signals. Understand the sectors. Explore the outlook.'],sectors:['See what moves the economy.','Inspect each sector model and explore clearly labelled what-if scenarios.'],data:['Every signal, in plain sight.','Official sources, original units, observation periods and publication dates.'],method:['Transparent by design.','Understand how the indicators become sector forecasts and aggregate GDP.']};
const viewName=()=>{const requested=location.hash.slice(1);if(['overview','sectors','data','method'].includes(requested))currentView=requested;return currentView;};
function notify(text,error=false){const el=$('#message');el.textContent=text;el.className=error?'error':'';el.hidden=!text;}
function setupQuarterOptions(){
 const last=Math.max(...data.gdp.map(r=>quarterIndex(r.quarter)))+1,old=$('#quarter-select').value;
 $('#quarter-select').innerHTML=Array.from({length:last-2023*4+1},(_,i)=>quarterLabel(last-i)).map(q=>`<option value="${q}">${period(q)}</option>`).join('');
 if([...$('#quarter-select').options].some(o=>o.value===old))$('#quarter-select').value=old;
 else{let chosen=quarterLabel(last);for(let q=last;q>=2023*4;q--){try{forecast(data,{quarter:quarterLabel(q),cutoff:$('#cutoff-input').value||today(),mode:'Auto'});chosen=quarterLabel(q);break;}catch{}}$('#quarter-select').value=chosen;}
}
function calculate(){
 $('#loading').hidden=true;
 try{
  result=forecast(data,{quarter:$('#quarter-select').value,cutoff:$('#cutoff-input').value,mode});review=reviewModel(data,result.stage,result.cutoff);
  $('#error-state').hidden=true;$('#view').hidden=false;$('#export-forecast').disabled=false;render();
 }catch(e){
  result=null;$('#view').hidden=true;$('#error-state').hidden=false;$('#export-forecast').disabled=true;
  $('#error-state').innerHTML=`<h2>This information set is not ready.</h2><p>${esc(e.message)}</p><p class="muted small section-spacer">Choose a later cutoff, select Auto, or refresh the official source data. No substitute forecast has been invented.</p><button class="text-button" id="error-auto">Use Auto stage ${icon('arrow')}</button>`;
  $('#error-auto').onclick=()=>{setMode('Auto');calculate();};
 }
 updateHeader();
}
function setMode(next){mode=next;$$('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));}
function updateHeader(){
 const v=viewName(),t=titles[v];$('#page-title').textContent=t[0];$('#page-subtitle').textContent=t[1];
 $$('[data-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.nav===v);if(el.dataset.nav===v)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
 $('#snapshot-short').textContent=`Snapshot · ${stamp(data.updatedAt)}`;
}
function render(){
 updateHeader();$('#view').innerHTML=({overview:overview,sectors:sectorLab,data:dataExplorer,method:methodology}[viewName()])();bindView();
}
const negativeClass=v=>v<0?'negative-text':'';
function trend(){
 const target=quarterIndex(result.quarter),rows=[];
 for(let q=target-chartRange+1;q<=target;q++){
  const label=quarterLabel(q),g=data.gdp.find(r=>r.quarter===label),base=data.gdp.find(r=>r.quarter===quarterLabel(q-4)),release=data.releases.gdp?.[label];
  let actual=g&&base&&release&&release<=result.cutoff?g.total/base.total-1:null,prediction=null;
  if(q===target)prediction=result.headline;
  else if(release){try{const cutoff=new Date(new Date(release+'T12:00:00Z').valueOf()-86400000).toISOString().slice(0,10);prediction=forecast(data,{quarter:label,cutoff,mode:result.stage}).headline;}catch{}}
  rows.push({quarter:label,actual,prediction});
 }
 const values=rows.flatMap(r=>[r.actual,r.prediction]).filter(isNumber);
 const W=660,H=225,L=40,R=20,T=14,B=35,low=Math.floor(Math.min(...values)*100-1),high=Math.ceil(Math.max(...values)*100+1),span=Math.max(high-low,2);
 const x=i=>L+i*(W-L-R)/(rows.length-1),y=v=>T+(high-v*100)/span*(H-T-B);
 const line=key=>{let p='',open=false;rows.forEach((r,i)=>{if(isNumber(r[key])){p+=`${open?'L':'M'}${x(i)},${y(r[key])} `;open=true;}else open=false;});return p;};
 let grid='';for(let i=0;i<=4;i++){const val=low+span*i/4,yy=y(val/100);grid+=`<line class="chart-grid" x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}"/><text class="chart-label" x="${L-9}" y="${yy+3}" text-anchor="end">${num(val,1)}%</text>`;}
 const labels=rows.map((r,i)=>`<text class="chart-label" x="${x(i)}" y="${H-11}" text-anchor="middle">${r.quarter.slice(2)}</text>`).join('');
 const dots=rows.map((r,i)=>isNumber(r.prediction)?`<circle class="chart-point" tabindex="0" role="img" aria-label="${r.quarter}: nowcast ${pct(r.prediction)}${isNumber(r.actual)?', published GDP '+pct(r.actual):''}" cx="${x(i)}" cy="${y(r.prediction)}" r="${i===rows.length-1?5:3}" fill="${i===rows.length-1?'#e1c600':'#fff'}" stroke="#bea800" stroke-width="1.8"><title>${r.quarter}: nowcast ${pct(r.prediction)}${isNumber(r.actual)?' · published GDP '+pct(r.actual):''}</title></circle>`:'').join('');
 return `<svg class="trend-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Published GDP and retrospective ${result.stage} nowcasts over the last ${chartRange} quarters">${grid}<path d="${line('actual')}" fill="none" stroke="#001a70" stroke-width="2.5"/><path d="${line('prediction')}" fill="none" stroke="#bea800" stroke-width="2" stroke-dasharray="4 4"/>${dots}${labels}</svg>`;
}
function overview(){
 const prev=data.gdp.find(r=>quarterIndex(r.quarter)===quarterIndex(result.quarter)-1),prior=prev&&data.gdp.find(r=>quarterIndex(r.quarter)===quarterIndex(prev.quarter)-4),previousGrowth=prev&&prior?prev.total/prior.total-1:null;
 const max=Math.max(...result.sectors.map(s=>Math.abs(s.contribution)));
 return `<div class="overview-top"><section class="hero-card" aria-label="Headline GDP nowcast"><div class="hero-top"><span class="hero-label">REAL GDP · YEAR-ON-YEAR</span><span class="badge">${result.stage} estimate</span></div><div class="hero-number">${num(result.headline*100,2)}<span>%</span></div><div class="hero-quarter">${period(result.quarter)} <span style="opacity:.4">/</span> Malaysia</div><div class="hero-bottom"><div><small>Forecast GDP level</small><strong>RM ${num(result.level/1000,1)} bn</strong></div><div><small>Information set</small><strong class="gold-text">${result.months} months${result.stage==='Pre-GDP'?' + quarterly':''}</strong></div></div></section>
 <section class="card"><div class="card-header"><div><h3>Growth, in perspective</h3><p>Quarterly real GDP · year-on-year change</p></div><select id="chart-range" class="mini-select" aria-label="Chart history length"><option value="8" ${chartRange===8?'selected':''}>Last 8 quarters</option><option value="12" ${chartRange===12?'selected':''}>Last 12 quarters</option></select></div><div class="chart-wrap">${trend()}</div><div class="legend"><span class="legend-item"><i class="legend-line"></i>Published GDP</span><span class="legend-item"><i class="legend-line forecast"></i>Nowcast · revised data</span></div></section></div>
 <div class="overview-stats"><section class="card stat-card"><span class="stat-icon">${icon('chart')}</span><div><small>Previous-quarter actual</small><div><strong>${pct(previousGrowth,1)}</strong><span class="stat-detail">${prev?period(prev.quarter):'Unavailable'}</span></div></div></section><section class="card stat-card"><span class="stat-icon">${icon('layers')}</span><div><small>Active forecast stage</small><div><strong style="font-size:18px">${result.stage}</strong><span class="stat-detail">${mode==='Auto'?'Automatically selected':'Manually selected'}</span></div></div></section><section class="card stat-card"><span class="stat-icon">${icon('clock')}</span><div><small>Revised-data review error</small><div><strong>${num(review.mae,2)}<span style="font-size:11px;font-weight:400"> pp</span></strong><span class="stat-detail">MAE · ${review.n}/6 quarters</span></div></div></section></div>
 <div class="overview-bottom"><section class="card"><div class="card-header"><div><h3>What drives the headline?</h3><p>Contribution to GDP growth · percentage points</p></div></div><div class="contribution-list">${result.sectors.map(s=>`<div class="contribution-row"><span>${s.short}</span><div class="bar-track"><i class="bar-fill ${s.contribution<0?'negative':''}" style="width:${Math.max(2,Math.abs(s.contribution)/max*100)}%;background:${s.color}"></i></div><strong class="${negativeClass(s.contribution)}">${pp(s.contribution)}</strong></div>`).join('')}</div><div class="card-footnote">Prior-year sector weights. Import duties complete the GDP total. ${result.sectors.some(s=>s.addFactorPP)?'Includes a fixed +0.20 pp services growth adjustment. See Sector lab.':'No fixed add factor applied to this forecast.'}</div></section>
 <section class="card"><div class="card-header"><div><h3>The sector picture</h3><p>Five production sectors, plus import duties</p></div><button class="text-button" data-go="sectors">Explore ${icon('arrow')}</button></div><div class="table-wrap"><table class="sector-table"><thead><tr><th>SECTOR</th><th>NOWCAST YoY</th><th>WEIGHT</th><th>METHOD</th></tr></thead><tbody>${result.sectors.map(s=>`<tr><td><button class="text-button" data-sector="${s.key}"><span class="sector-dot" style="background:${s.color}"></span>${s.short}</button></td><td class="growth-number ${negativeClass(s.growth)}">${pct(s.growth,1)}</td><td>${pct(s.weight,1)}</td><td><span class="method-pill">${s.method}</span></td></tr>`).join('')}</tbody></table></div></section></div>
 <div class="information-strip">${icon('info')}<div><strong>${mode==='Auto'?`Auto selected ${result.stage}.`:result.stage+' stage selected.'}</strong> ${result.stage==='Early'&&mode==='Auto'?'Same-quarter services volume and construction statistics, plus the required third-month observations, must be available before Pre-GDP activates.':'The fit uses GDP strictly before the selected quarter.'} <a href="#method">See the methodology</a>. ${isNumber(result.actual)?`Selected-quarter GDP is now published (${pct(result.actual)}); it was excluded from training.`:'Target-quarter regular GDP is not available in this information set.'}</div></div>`;
}
function fitEquation(s){
 const b=s.bridge,a=s.ar;
 const btext=b?`${num(b.intercept*100,3)} + ${num(b.slope,3)} × indicator YoY (%)`:'';
 const atext=a?`${num(a.intercept*100,3)} + ${num(a.slope,3)} × prior-quarter GDP YoY (%)`:'';
 return s.method==='Persistence'?'Forecast = previous-quarter sector GDP YoY':s.method==='Bridge'?`Forecast (%) = ${btext}`:s.method==='AR(1)'?`Forecast (%) = ${atext}`:`Bridge (%) = ${btext}<br>AR (%) = ${atext}<br>Forecast = ½ Bridge + ½ AR`;
}
function sectorLab(){
 const s=result.sectors.find(s=>s.key===selectedSector)||result.sectors[4];
 const fits=[['Indicator bridge',s.bridge],['GDP AR(1)',s.ar]].filter(r=>r[1]);
 const sc=scenario(result,adjustments);
 return `<div class="sector-tabs" role="group" aria-label="Inspect a sector">${result.sectors.map(s=>`<button class="sector-tab ${s.key===selectedSector?'active':''}" data-sector="${s.key}" aria-pressed="${s.key===selectedSector}">${s.short}</button>`).join('')}</div><div class="lab-grid"><section class="card sector-detail"><div class="detail-header"><div><div class="eyebrow">${result.stage.toUpperCase()} SECTOR MODEL</div><h2>${s.name}</h2></div><span class="badge">${s.method}</span></div><div class="detail-number ${negativeClass(s.growth)}">${pct(s.growth)}</div><p class="muted small">Baseline real GDP growth · ${period(result.quarter)}</p><p class="muted small">Unadjusted model: ${pct(s.rawGrowth)} · Fixed historical add factor: ${pp(s.addFactorPP)} pp. Applied before aggregation.</p><div class="detail-metrics"><div><span>GDP contribution</span><strong>${pp(s.contribution)} pp</strong></div><div><span>Prior-year weight</span><strong>${pct(s.weight,1)}</strong></div><div><span>Forecast level</span><strong>${num(s.level/1000,1)} bn</strong></div></div><div class="equation"><div class="equation-title">The fitted equation</div><p>${fitEquation(s)}</p></div><div class="detail-source"><strong>Signal:</strong> ${s.indicator}${isNumber(s.signal)?` · ${pct(s.signal)} YoY`:''}<br><strong>Window:</strong> ${s.method==='Persistence'?'No regression':s.window?`${s.window} latest valid prior quarters`:'All valid prior history'} · minimum 12 observations for regressions.</div>${fits.length?`<table class="fit-table"><thead><tr><th>Fit</th><th>Observations</th><th>Training period</th></tr></thead><tbody>${fits.map(([name,f])=>`<tr><td>${name}</td><td>${f.n}</td><td>${f.from}–${f.through}</td></tr>`).join('')}</tbody></table>`:''}<div class="lab-note">GDP values are RM billion at constant 2015 prices. The target quarter is excluded from coefficient estimation.</div></section>
 <section class="card scenario-card"><div class="scenario-title"><div><div class="eyebrow">WHAT-IF SANDBOX</div><h2>Explore a different path.</h2></div><button id="reset-scenario" class="text-button">Reset</button></div><p class="muted small" style="margin-top:8px">Adjust sector growth assumptions. The baseline forecast and source data stay intact.</p><div class="scenario-result"><div><small>Scenario GDP growth</small><strong id="scenario-headline">${pct(sc.headline)}</strong></div><div style="text-align:right"><small>Change vs baseline</small><span class="scenario-delta" id="scenario-delta">${pp((sc.headline-result.headline)*100)} pp</span></div></div>${result.sectors.map(s=>{const limit=s.key==='duties'?10:3;return `<div class="slider-row"><div class="slider-label"><label for="slider-${s.key}">${s.name}</label><output id="output-${s.key}">${pp(adjustments[s.key]||0,1)} pp</output></div><input type="range" id="slider-${s.key}" data-slider="${s.key}" min="-${limit}" max="${limit}" step="0.1" value="${adjustments[s.key]||0}" aria-label="${s.name} growth adjustment in percentage points"><div class="slider-scale"><span>−${limit} pp</span><span>Baseline ${pct(s.growth,1)}</span><span>+${limit} pp</span></div></div>`;}).join('')}<div class="lab-note">Scenario results are assumptions, not an additional model forecast or a confidence interval. Each adjustment is applied to the prior-year component level before GDP is re-aggregated.</div></section></div>`;
}
function explorerRows(){
 const year=explorer.year,include=s=>year==='all'||String(s).startsWith(year);
 if(explorer.type==='monthly')return {headers:['Month','CPO (tonnes)','Mining IPI (2015=100)','Manufacturing IPI (2015=100)','Retail volume (2015=100)'],csv:['month','cpo_tonnes','mining_index_2015_100','manufacturing_index_2015_100','retail_volume_2015_100'],rows:data.monthly.filter(r=>include(r.date)).map(r=>[r.date,r.cpo,r.mining,r.manufacturing,r.retail]),format:(r)=>[period(r[0]),num(r[1],0),...r.slice(2).map(v=>num(v,3))],note:'CPO, mining and manufacturing use 2 or 3 months. Retail is the services predictor only in Early stage.'};
 if(explorer.type==='quarterly')return {headers:['Quarter','Services volume (2015=100)','Services published','Construction work (RM thousand)','Construction published'],csv:['quarter','services_volume_2015_100','services_publication','construction_work_rm_thousand','construction_publication'],rows:data.quarterly.filter(r=>include(r.quarter)).map(r=>[r.quarter,r.servicesVolume,r.servicesPublished,r.constructionWork,r.constructionPublished]),format:r=>[period(r[0]),num(r[1],1),r[2]?dateStr(r[2]):'Unverified',num(r[3],0),r[4]?dateStr(r[4]):'Unverified'],note:'Construction work is nominal, in RM thousand. Regression maps its YoY growth to real construction value-added growth.'};
 if(explorer.type==='gdp')return {headers:['Quarter',...SECTORS.map(s=>s.short),'Total GDP'],csv:['quarter',...SECTORS.map(s=>s.key+'_rm_million_constant_2015'),'total_rm_million_constant_2015'],rows:data.gdp.filter(r=>include(r.quarter)).map(r=>[r.quarter,...SECTORS.map(s=>r[s.key]),r.total]),format:r=>[period(r[0]),...r.slice(1).map(v=>num(v,1))],note:'All GDP levels are RM million at constant 2015 prices. Only GDP quarters before the selected target enter the fit.'};
 const rows=[];
 for(const [source,entries] of Object.entries(data.releases))for(const [period,date] of Object.entries(entries))if(include(period))rows.push([source==='ipi'?'Industrial production':source==='retail'?'Retail volume':'Regular GDP',period,date,date<=result.cutoff?'By cutoff':'After cutoff']);
 for(const r of data.quarterly)if(include(r.quarter))for(const [name,key] of [['Services volume','servicesPublished'],['Construction work','constructionPublished']])if(r[key])rows.push([name,r.quarter,r[key],r[key]<=result.cutoff?'By cutoff':'After cutoff']);
 rows.sort((a,b)=>a[2].localeCompare(b[2]));return {headers:['Source','Observation period','Publication date','Cutoff status'],csv:['source','observation_period','publication_date','cutoff_status'],rows,format:r=>[r[0],period(r[1]),dateStr(r[2]),r[3]],note:'Actual release dates are verified from DOSM archives. Unverified dates never activate the late stage. CPO pages do not supply a historical release-date series.'};
}
function dataExplorer(){
 const t=explorerRows(),years=[...new Set([...data.monthly.map(r=>r.date.slice(0,4)),...data.gdp.map(r=>r.quarter.slice(0,4))])].sort().reverse();
 return `<div class="section-intro"><div><h2>The source dashboard</h2><p>Snapshot ${stamp(data.updatedAt)} · ${data.snapshotType==='official-source-refresh'?'Complete official-source refresh':'Approved workbook import'}</p></div></div><div class="source-grid">${data.sources.map(s=>`<section class="card source-card"><div class="provider">${s.provider} · ${s.frequency.toUpperCase()}</div><h3>${esc(s.name)}</h3><div class="latest">${period(s.latest)}</div><div class="unit">${esc(s.units)}<br>${num(s.observations,0)} observations</div><a class="source-link" href="${esc(s.url)}" target="_blank" rel="noreferrer">Official source ${icon('external')}</a></section>`).join('')}</div><section class="card"><div class="explorer-head"><div class="explorer-controls"><select id="dataset-select" aria-label="Dataset"><option value="monthly" ${explorer.type==='monthly'?'selected':''}>Monthly indicators</option><option value="quarterly" ${explorer.type==='quarterly'?'selected':''}>Quarterly indicators</option><option value="gdp" ${explorer.type==='gdp'?'selected':''}>GDP history</option><option value="calendar" ${explorer.type==='calendar'?'selected':''}>Publication calendar</option></select><select id="data-year" aria-label="Filter source data by year"><option value="all" ${explorer.year==='all'?'selected':''}>All years</option>${years.map(y=>`<option ${explorer.year===y?'selected':''}>${y}</option>`).join('')}</select><button id="export-data" class="button secondary">${icon('download')}Download CSV</button></div></div><div class="table-wrap"><table class="data-table"><thead><tr>${t.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(r=>`<tr>${t.format(r).map(c=>`<td class="${c==='—'?'muted-cell':''}">${esc(c)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${t.headers.length}" class="table-empty">No observations for this year.</td></tr>`}</tbody></table></div><div class="data-meta"><span>${t.rows.length} rows shown · raw units preserved in CSV</span><span>Cutoff ${dateStr(result.cutoff)}</span></div></section><div class="information-strip">${icon('info')}<div>${esc(t.note)} Source data are revised snapshots; changing the cutoff checks publication timing but does not recreate original-release vintages.</div></div>`;
}
function methodology(){
 return `<div class="method-grid"><section class="card method-card"><div class="eyebrow">FROM INDICATORS TO GDP</div><h2>A transparent five-sector bridge model.</h2><p>The approved Excel specification is implemented in the browser. The five production sectors are forecast separately, and import duties are added to reconcile the official supply-side GDP total.</p><ol class="method-steps"><li><span class="step-number">01</span><div><h3>Choose the information set</h3><p>Auto uses the first two months in Early stage. It switches to Pre-GDP only when same-quarter services volume, construction work done and the required three monthly observations have been published by the cutoff. Forced Pre-GDP stops when incomplete.</p></div></li><li><span class="step-number">02</span><div><h3>Convert levels into comparable signals</h3><p>Monthly signal = sum of the first 2 or 3 months ÷ the same months a year earlier − 1. Quarterly signal = indicator level ÷ its level four quarters earlier − 1. Seasonally unadjusted original levels are used for YoY comparisons.</p></div></li><li><span class="step-number">03</span><div><h3>Fit only to earlier GDP quarters</h3><p>Bridge regressions map an indicator to sector GDP YoY. AR(1) uses the preceding quarter’s GDP growth. A Blend averages bridge and AR forecasts equally. Persistence repeats the last quarter’s growth. Regression requires at least 12 valid prior observations.</p></div></li><li><span class="step-number">04</span><div><h3>Rebuild the real GDP level</h3><p>Apply each sector’s YoY forecast to its official prior-year real GDP level, add all five sectors and duties, then divide by official prior-year total GDP.</p></div></li></ol><div class="formula-box">Sector level = prior-year sector level × (1 + forecast growth)<br>GDP growth = Σ forecast component levels ÷ prior-year official total GDP − 1</div><p>Official-total rounding differences are retained. Net exports are not added: they were tested and did not improve the review accuracy, and adding expenditure net exports directly to production-sector GDP would double-count activity.</p></section>
 <section class="card method-card"><div class="eyebrow">ACTIVE SPECIFICATION</div><h2>${result.stage}: the selected sector models</h2><div class="table-wrap"><table class="data-table review-table"><thead><tr><th>Component</th><th>Method</th><th>Fit window</th></tr></thead><tbody>${result.sectors.map(s=>`<tr><td>${s.short}</td><td>${s.method}</td><td>${s.method==='Persistence'?'No fit':s.window?s.window+' quarters':'All history'}</td></tr>`).join('')}</tbody></table></div><div class="method-mini"><h3>Predictors in this stage</h3><p>${result.stage==='Early'?'Agriculture: CPO + GDP AR. Mining: mining IPI. Manufacturing: manufacturing IPI. Construction: prior-quarter GDP growth. Services: retail volume + GDP AR. Duties: GDP AR.':'Agriculture: full-quarter CPO + GDP AR. Mining and manufacturing: full-quarter IPI. Construction: same-quarter nominal work done. Services: same-quarter original volume index. Duties: GDP AR.'}</p></div><div class="method-mini"><h3>Fixed historical add factors</h3><p>From Q3 2026 and cutoffs on or after 12 November 2026, Pre-GDP services growth includes +0.20 percentage points. All other sector and Early factors are zero. The magnitude is the rounded 2023–2024 mean forecast shortfall, checked against 2025Q1–2026Q2. It is frozen across data updates and is not targeted to DOSM’s Q3 advance result. Sector lab shows the unadjusted model and factor. Historical review below retains the original forecasts; it does not claim validation of the adjusted specification. The six-quarter check was used to select this policy and is not an independent test.</p></div><div class="method-mini"><h3>Revised-data forecast review</h3><p>Selection period: 2023–2024. Review: 2025Q1–2026Q2. The six-quarter review has been reused in model work and is not an independent accuracy guarantee. Refreshed source revisions can change the results.</p></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Quarter</th><th>Actual</th><th>Model</th><th>Error (pp)</th></tr></thead><tbody>${review.rows.map(r=>`<tr><td>${r.quarter}</td><td>${pct(r.actual)}</td><td>${pct(r.prediction)}</td><td title="${esc(r.error||'')}">${isNumber(r.errorPP)?pp(r.errorPP):'Unavailable'}</td></tr>`).join('')}</tbody></table></div><div class="method-mini"><h3>MAE ${num(review.mae,3)} pp · RMSE ${num(review.rmse,3)} pp</h3><p>${review.n} of 6 review forecasts have the required data. Error bands have not been calibrated as confidence intervals.</p></div><details class="disclosure"><summary>Cutoffs and historical revisions</summary><p>Monthly IPI/retail and quarterly releases are checked against verified publication dates. Unknown dates prevent eligibility. MPOB pages provide observed CPO levels but not a complete historical release calendar. The data snapshot contains the latest revised observations; selecting an older cutoff is a retrospective exercise, not an original-vintage real-time backtest.</p></details><details class="disclosure"><summary>How the update button works</summary><p>The local server downloads, validates and atomically replaces the official snapshot. On GitHub Pages, scheduled or manually dispatched GitHub Actions performs the same operation. A failed source refresh does not overwrite the last successful snapshot or deployment. Refreshing the browser alone loads the latest published snapshot; it cannot independently run a GitHub workflow without GitHub authentication.</p></details><details class="disclosure"><summary>Construction and nominal data</summary><p>Construction work done is nominal output in RM thousand. Its growth is mapped statistically to real construction GDP growth. It is not treated as real value added or inserted directly into GDP.</p></details></section></div>`;
}
function bindView(){
 $$('[data-go]').forEach(b=>b.onclick=()=>location.hash=b.dataset.go);
 $$('[data-sector]').forEach(b=>b.onclick=()=>{selectedSector=b.dataset.sector;if(viewName()!=='sectors')location.hash='sectors';else render();});
 if($('#chart-range'))$('#chart-range').onchange=e=>{chartRange=+e.target.value;render();};
 if($('#reset-scenario'))$('#reset-scenario').onclick=()=>{adjustments={};render();};
 $$('[data-slider]').forEach(el=>el.oninput=()=>{adjustments[el.dataset.slider]=+el.value;const s=scenario(result,adjustments);$(`#output-${el.dataset.slider}`).textContent=pp(+el.value,1)+' pp';$('#scenario-headline').textContent=pct(s.headline);$('#scenario-delta').textContent=pp((s.headline-result.headline)*100)+' pp';});
 if($('#dataset-select'))$('#dataset-select').onchange=e=>{explorer.type=e.target.value;render();};
 if($('#data-year'))$('#data-year').onchange=e=>{explorer.year=e.target.value;render();};
 if($('#export-data'))$('#export-data').onclick=()=>{const t=explorerRows();downloadCSV(`malaysia-${explorer.type}-${explorer.year}.csv`,t.csv,t.rows);};
}
function download(name,text,type){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function downloadCSV(name,headers,rows){const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';download(name,[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
$('#export-forecast').onclick=()=>{if(result)downloadCSV(`gdp-nowcast-${result.quarter}-${result.stage}.csv`,['quarter','cutoff','stage','component','method','growth_yoy_decimal','prior_year_gdp_rm_million','forecast_gdp_rm_million','contribution_pp','snapshot_updated_at','raw_growth_yoy_decimal','fixed_add_factor_pp'],[...result.sectors.map(s=>[result.quarter,result.cutoff,result.stage,s.name,s.method,s.growth,s.base,s.level,s.contribution,data.updatedAt,s.rawGrowth,s.addFactorPP]),[result.quarter,result.cutoff,result.stage,'Total GDP','Official component aggregation',result.headline,result.priorGDP,result.level,result.headline*100,data.updatedAt,'','']]);};
$('#download-snapshot').onclick=()=>download('malaysia-gdp-model-snapshot.json',JSON.stringify(data,null,2),'application/json');
$('#print-button').onclick=()=>window.print();
$('#quarter-select').onchange=()=>{adjustments={};calculate();};$('#cutoff-input').onchange=()=>{adjustments={};calculate();};
$$('[data-mode]').forEach(b=>b.onclick=()=>{setMode(b.dataset.mode);adjustments={};calculate();});
window.addEventListener('hashchange',()=>{if(result)render();else updateHeader();});
$$('.dialog-close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
function repo(){try{return localStorage.getItem('gdp-nowcast-repository')||config.repository||inferRepo();}catch{return config.repository||inferRepo();}}
function inferRepo(){if(location.hostname.endsWith('.github.io')){const owner=location.hostname.split('.')[0],project=location.pathname.split('/').filter(Boolean)[0]||`${owner}.github.io`;return `${owner}/${project}`;}return '';}
function settings(){ $('#repository-input').value=repo();$('#settings-message').textContent='';$('#settings-dialog').showModal();}
$('#settings-button').onclick=settings;
$('#settings-top').onclick=settings;
$('#save-settings').onclick=()=>{const value=$('#repository-input').value.trim();if(!/^[a-zA-Z0-9_.-]+\/[a-zA-Z0-9_.-]+$/.test(value)){$('#settings-message').textContent='Enter owner/repository, without a URL or access token.';return;}try{localStorage.setItem('gdp-nowcast-repository',value);}catch{config.repository=value;}$('#settings-dialog').close();notify('Repository saved. Source refreshes run securely on GitHub.');};
$('#update-settings-link').onclick=()=>{$('#update-dialog').close();settings();};
function setBusy(value){busy=value;$('#refresh-button').disabled=value;$('#refresh-button').classList.toggle('loading-spin',value);$('#refresh-label').textContent=value?'Updating sources…':'Update data';}
async function loadPublished(){const response=await fetch('./data/model-data.json?updated='+Date.now(),{cache:'no-store'});if(!response.ok)throw new Error('The published source snapshot could not be loaded.');const next=await response.json();if(next.schemaVersion!==1||!Array.isArray(next.gdp))throw new Error('Unexpected snapshot schema.');return next;}
async function checkPublished(){
 const status=$('#update-status'),before=data.snapshotId;status.textContent='Checking the latest published snapshot…';
 try{data=await loadPublished();setupQuarterOptions();calculate();status.textContent=data.snapshotId!==before?`Loaded a new source snapshot: ${stamp(data.updatedAt)}.`:`No newer snapshot has been published. Current snapshot: ${stamp(data.updatedAt)}. If a workflow is running, check again after it finishes.`;notify(status.textContent);}catch(e){status.textContent=e.message;}
}
$('#check-update').onclick=checkPublished;
$('#refresh-button').onclick=async()=>{
 if(busy)return;
 if(local){
  setBusy(true);notify('Downloading official sources and publication calendars. The current result stays in place until the complete snapshot is validated.');
  try{const response=await fetch('./api/refresh',{method:'POST',headers:{'Content-Type':'application/json','X-Nowcast-Refresh':'1'},body:'{}'});const body=await response.json();if(!response.ok)throw new Error(body.error||'Source refresh failed.');data=await loadPublished();setupQuarterOptions();calculate();notify(`Official sources refreshed at ${stamp(data.updatedAt)}. The model has been recalculated.`);}
  catch(e){notify(`${e.message} The preceding snapshot and forecast are retained.`,true);}finally{setBusy(false);}return;
 }
 const repository=repo(),link=$('#workflow-link');
 if(repository){link.href=`https://github.com/${repository}/actions/workflows/${encodeURIComponent(config.workflow)}`;link.hidden=false;$('#update-status').textContent=`Repository: ${repository}. Open the workflow, choose Run workflow, then return here to load the published update.`;}
 else{link.hidden=true;$('#update-status').textContent='Configure your GitHub repository first, or check for a newer published snapshot. No access token is needed.';}
 $('#update-dialog').showModal();
};
async function init(){
 try{
  const response=await fetch('./config.json',{cache:'no-store'});if(response.ok)config={...config,...await response.json()};
  data=await loadPublished();explorer.year=data.monthly.at(-1).date.slice(0,4);$('#cutoff-input').value=today();$('#cutoff-input').max=today();setupQuarterOptions();
  if(['localhost','127.0.0.1'].includes(location.hostname)){try{const caps=await fetch('./api/capabilities').then(r=>r.json());local=!!caps.refresh;}catch{}}
  calculate();
  const age=Math.floor((Date.now()-Date.parse(data.updatedAt))/86400000);if(age>4)notify(`The published source snapshot is ${age} days old (${stamp(data.updatedAt)}). Refresh official sources before treating this as a current outlook.`,true);
 }catch(e){$('#loading').hidden=true;$('#error-state').hidden=false;$('#error-state').textContent=e.message;}
}
init();
